<section class="admin-v2-page-intro"><div><span class="admin-v2-eyebrow">PUBLIC CONTENT</span><h2>إدارة الصفحات</h2><p>أنشئ الصفحات العامة وعدّلها وانشرها أو انقلها إلى السلة مع الحفاظ على روابطها.</p></div></section>
<section class="admin-v2-panel"><form method="post" action="/admin-v2/pages/save" class="admin-v2-actions"><input type="hidden" name="_token" value="<?=e(App\Core\Csrf::token())?>"><input type="hidden" name="id" value="<?=e($formPage['id']??0)?>"><div class="admin-v2-grid-2"><label>الصفحة الحالية<select onchange="location.href=this.value?'/admin-v2/pages?edit='+this.value:'/admin-v2/pages'"><option value="0">صفحة جديدة</option><?php foreach($pages as $page): if($page['deleted_at']===null): ?><option value="<?=e($page['id'])?>" <?=((int)($editId??0)===(int)$page['id'])?'selected':''?>><?=e($page['title']?:'بدون عنوان')?> — #<?=e($page['id'])?></option><?php endif; endforeach; ?></select></label><label>اللغة<select name="locale"><option value="ar">العربية</option><option value="en">English</option><option value="es">Español</option><option value="fr">Français</option><option value="ru">Русский</option></select></label></div><label>العنوان<input name="title" required maxlength="255" value="<?=e($formPage['title']??'')?>"></label><label>Slug<input name="slug" required maxlength="220" dir="ltr" value="<?=e($formPage['slug']??'')?>"></label><label>المحتوى<textarea name="content" rows="9"><?=e($formPage['content']??'')?></textarea></label><label>الحالة<select name="status"><option value="draft" <?= (($formPage['status']??'draft')==='draft')?'selected':''?>>مسودة</option><option value="published" <?= (($formPage['status']??'')==='published')?'selected':''?>>منشورة</option></select></label><div class="admin-v2-inline-actions"><button class="admin-v2-button primary" type="submit"><?=($formPage?'تحديث الصفحة':'حفظ الصفحة')?></button><?php if($formPage): ?><a class="admin-v2-button" href="/admin-v2/pages">صفحة جديدة</a><?php endif; ?></div></form></section>
<section class="admin-v2-table-panel"><div class="admin-v2-panel-head"><h3>الصفحات الحالية</h3><span><?=e(count($pages))?></span></div><div class="admin-v2-responsive-table"><table class="admin-v2-table"><thead><tr><th>العنوان</th><th>الرابط</th><th>الحالة</th><th>إجراءات</th></tr></thead><tbody><?php foreach($pages as $page): ?><tr><td><strong><?=e($page['title']?:'بدون عنوان')?></strong><small>#<?=e($page['id'])?></small></td><td dir="ltr"><?=e($page['slug']?:'—')?></td><td><?=e($page['deleted_at']?'في السلة':$page['status'])?></td><td class="admin-v2-inline-actions"><?php if(!$page['deleted_at']): ?><a class="admin-v2-button" href="/admin-v2/pages?edit=<?=e($page['id'])?>">تحرير</a><?php endif; ?><form method="post" action="/admin-v2/pages/status"><input type="hidden" name="_token" value="<?=e(App\Core\Csrf::token())?>"><input type="hidden" name="id" value="<?=e($page['id'])?>"><input type="hidden" name="action" value="<?=$page['deleted_at']?'restore':'toggle'?>"><button class="admin-v2-button" type="submit"><?=$page['deleted_at']?'استعادة':($page['status']==='published'?'إلغاء النشر':'نشر')?></button></form><?php if(!$page['deleted_at']): ?><form method="post" action="/admin-v2/pages/status"><input type="hidden" name="_token" value="<?=e(App\Core\Csrf::token())?>"><input type="hidden" name="id" value="<?=e($page['id'])?>"><input type="hidden" name="action" value="trash"><button class="admin-v2-button" type="submit">نقل للسلة</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<?php if($formPage && !empty($formPage['slug'])): ?><section class="admin-v2-panel"><div class="admin-v2-inline-actions"><strong>الصفحة المحددة: <?=e($formPage['title']??'')?></strong><a class="admin-v2-button primary" href="<?=e(locale_url('ar','page/'.(string)$formPage['slug']))?>" target="_blank" rel="noopener">معاينة الصفحة في الموقع</a></div></section><?php endif; ?>
